"""Blind continuous-session annotation page; shares the existing local save API."""

HTML = r"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Salience · Continuous review</title>
<style>:root{color-scheme:dark;font:16px system-ui;background:#10151d;color:#e7edf5}body{max-width:1050px;margin:auto;padding:24px}p{line-height:1.5;color:#bdc9d9}video{width:100%;max-height:65vh;background:black}button,input,textarea{font:inherit;background:#202e40;color:#eef4ff;border:1px solid #52657f;border-radius:7px;padding:9px;margin:4px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}textarea{width:95%;min-height:60px}article{background:#182230;padding:14px;border-radius:8px;margin:10px 0}[hidden]{display:none!important}#saved{color:#98dcbb}.warning{color:#f3cb96}label{display:block;margin:12px 0}</style>
<h1>Five-minute gameplay review</h1>
<p>Watch the full sequence and mark every moment you would want saved, including worthwhile build plays without a kill. Leaving no moments is valid. Model proposals stay hidden until you finish.</p>
<p class="warning">Saved footage only. The recorder remains paused because of the reported FPS drops and crashes.</p>
<video id="video" controls preload="metadata" src="continuous.mp4"></video>
<div><button id="start">Start wanted moment here</button><button id="end">End and save moment</button><button id="cancel" hidden>Cancel mark</button><span id="mark"></span></div>
<textarea id="note" aria-label="Moment note" placeholder="Optional: what makes this moment worth saving?"></textarea>
<p id="saved" role="status"></p><div id="events"></div>
<label><input id="complete" type="checkbox"> I watched the full sequence and marked every moment I would keep (including none).</label>
<button id="reveal" disabled>Show model proposals</button>
<section id="model" hidden><h2>Model proposals</h2><p>These are event proposals, not personalized keep decisions. Times are estimated; descriptions may contain errors. “No proposal” can mean an event was missed.</p><div id="proposals"></div><pre id="metrics" style="white-space:pre-wrap"></pre></section>
<script>
const $=id=>document.getElementById(id),video=$('video');let review,begin=null,chain=Promise.resolve(),ready=false;
const time=t=>Math.floor(t/60)+':'+(t%60).toFixed(1).padStart(4,'0');
function save(){const body=JSON.stringify(review);$('saved').textContent='Saving…';chain=chain.catch(()=>{}).then(async()=>{const r=await fetch('/labels',{method:'POST',headers:{'Content-Type':'application/json'},body});if(!r.ok)throw Error(await r.text());$('saved').textContent='Saved locally';});chain.catch(e=>$('saved').textContent='Save failed: '+e.message);return chain}
function render(){$('events').replaceChildren();review.events.forEach((e,i)=>{const a=document.createElement('article'),text=document.createElement('p');text.textContent=time(e.start)+'–'+time(e.end)+(e.notes?' · '+e.notes:'');const play=document.createElement('button');play.textContent='Play from here';play.onclick=()=>{video.currentTime=e.start;video.play()};const remove=document.createElement('button');remove.textContent='Remove';remove.onclick=async()=>{review.events.splice(i,1);review.timeline_review_complete=false;$('complete').checked=false;$('reveal').disabled=true;$('model').hidden=true;await save();render()};a.append(text,play,remove);$('events').append(a)})}
$('start').onclick=()=>{if(!ready)return;begin=video.currentTime;$('mark').textContent='Start '+time(begin);$('cancel').hidden=false};
$('cancel').onclick=()=>{begin=null;$('mark').textContent='';$('cancel').hidden=true};
$('end').onclick=async()=>{if(!ready)return;const end=video.currentTime;if(begin===null||end<=begin){$('saved').textContent='Mark a start before the end.';return}review.events.push({start:begin,end,notes:$('note').value});review.timeline_review_complete=false;$('complete').checked=false;$('reveal').disabled=true;$('model').hidden=true;begin=null;$('mark').textContent='';$('cancel').hidden=true;$('note').value='';await save();render()};
$('complete').onchange=async()=>{if(!ready)return;review.timeline_review_complete=$('complete').checked;$('reveal').disabled=true;$('model').hidden=true;try{await save();$('reveal').disabled=!review.timeline_review_complete}catch(e){$('saved').textContent=e.message}};
$('reveal').onclick=async()=>{if(!review.timeline_review_complete)return;try{await chain;const data=await fetch('metrics.json').then(r=>r.json());$('proposals').replaceChildren();for(const e of data.proposals){const a=document.createElement('article');const p=document.createElement('p');p.textContent=time(e.start)+'–'+time(e.end)+' · '+e.kind+' · '+e.actor+' · '+e.evidence;const b=document.createElement('button');b.textContent='Inspect proposal';b.onclick=()=>{video.currentTime=Math.max(0,e.start-3);video.play()};a.append(p,b);$('proposals').append(a)}if(!data.proposals.length)$('proposals').textContent='No events proposed.';const m=data.user_highlight_metrics;$('metrics').textContent=data.missing_chunks.length?'Evaluation incomplete; '+data.missing_chunks.length+' chunks pending.':m?'Wanted moments overlapped: '+m.events_found+' / '+m.wanted_moments+'\nUnwanted proposals per hour: '+m.unwanted_proposals_per_hour.toFixed(1)+'\nTemporal overlap only; this does not grade clip boundaries or description accuracy.':'Review metrics pending.';$('model').hidden=false}catch(e){$('saved').textContent='Could not load proposals: '+e.message}};
fetch('user-labels.json').then(r=>r.json()).then(r=>{review=r;ready=true;$('complete').checked=!!r.timeline_review_complete;$('reveal').disabled=!r.timeline_review_complete;render()}).catch(e=>$('saved').textContent='Could not load saved review: '+e.message);
</script></html>"""
